// Курс «30 дней с Евой»: короткий урок + одно маленькое задание в день.
// Названия уроков продублированы на сервере (COURSE_TITLES) для вечерних напоминаний —
// при правке названий обнови оба места.

enum CourseAction { none, eva, cosmetologist, scanner, calendar, shopping }

class CourseLesson {
  final int day;
  final String emoji;
  final String title;
  final String body;
  final String task;
  final CourseAction action;
  final String actionLabel;
  final String? evaPrompt;
  const CourseLesson(this.day, this.emoji, this.title, this.body, this.task, {this.action = CourseAction.none, this.actionLabel = '', this.evaPrompt});
}

class CourseContent {
  CourseContent._();

  static const int freeDays = 3;

  static const List<String> weeks = ['Основы', 'Цикл и питание', 'Магазин и кухня', 'Тело и привычки', 'Финиш'];

  static String weekOf(int day) => day <= 7 ? weeks[0] : day <= 14 ? weeks[1] : day <= 21 ? weeks[2] : day <= 28 ? weeks[3] : weeks[4];

  static const List<CourseLesson> lessons = [
    CourseLesson(1, '🍽', 'Тарелка, которая работает',
        'Забудь про подсчёт каждой крошки — начнём с простой схемы. Половина тарелки — овощи или зелень. Четверть — белок: курица, рыба, яйца, творог, бобовые. Ещё четверть — сложные углеводы: крупы, цельнозерновой хлеб, картофель.\n\nТакая тарелка сама держит калории в разумных рамках, даёт сытость на 3–4 часа и не требует весов.',
